 921	\begin{lemma}[Combined point measurements]
 922		\label{lem:qld-4-10}
 923		\lean{MIPStarRE.QPBT.CombinedPointsWitness}
 924		\lean{MIPStarRE.QPBT.exists_combinedPointsWitness}
 925		\leanok
 926		\uses{def:expanded-state, def:expanded-point-measurement,
 927			def:povm-distance, def:symmetric-equivalents}
 928		There exists a function $\delta_Q(\eps) = \poly(\eps)$ such that the
 929		following holds. For every $x, z \in \F_q^m$ and
 930		$\hilb \in \{\hilb_{\mathsf{A}}, \hilb_{\mathsf{B}}\}$ there are
 931		projective measurements $\{\hat{Q}^{x,z}_{a,b}\}_{a,b \in \F_q}$ acting
 932		on $\hilb \ot (\C^q)^{\ot M}$ such that:
 933		\begin{enumerate}
 934			\item (\textbf{Self-consistency}) On average over uniformly random
 935			$x, z \in \F_q^m$,
 936			\begin{equation}
 937				\label{eq:qld-q-self-cons}
 938				(\hat{Q}^{x,z}_{a,b})_{\mathsf{A}\mathsf{A}'}
 939				\approx_{\delta_Q}
 940				(\hat{Q}^{x,z}_{a,b})_{\mathsf{B}\mathsf{A}''}\,.
 941			\end{equation}
 942			\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly
 943			random $x, z \in \F_q^m$,
 944			\begin{gather}
 945				\label{eq:qld-q-cons-m-hat-xz}
 946				(\hat{Q}^{x,z}_{a,b})_{\mathsf{A}\mathsf{A}'}
 947				\approx_{\delta_Q}
 948				(\hat{M}^{(\mathrm{Point},X),x}_{a} \,
 949				\hat{M}^{(\mathrm{Point},Z),z}_{b})_{\mathsf{B}\mathsf{A}''}\,,
 950				\\
 951				\label{eq:qld-q-cons-m-hat-zx}
 952				(\hat{Q}^{x,z}_{a,b})_{\mathsf{A}\mathsf{A}'}
 953				\approx_{\delta_Q}
 954				(\hat{M}^{(\mathrm{Point},Z),z}_{b} \,
 955				\hat{M}^{(\mathrm{Point},X),x}_{a})_{\mathsf{B}\mathsf{A}''}\,.
 956			\end{gather}
 957		\end{enumerate}
 958		Furthermore, all symmetric equivalents of these approximations also hold.
 959		The operators $\hat{M}^{(\mathrm{Point},X),x}_{a}$ and
 960		$\hat{M}^{(\mathrm{Point},Z),z}_{b}$ do not commute in general, so the
 961		products in \eqref{eq:qld-q-cons-m-hat-xz} and
 962		\eqref{eq:qld-q-cons-m-hat-zx} differ and the two relations are separate
 963		conclusions.
 964	\end{lemma}
